package trie_test

import (
	"sort"
	"testing"

	"github.com/ai-verification/trie/trie"
)

func TestInsertSearch(t *testing.T) {
	tr := trie.New()
	tr.Insert("apple")
	tr.Insert("app")
	if !tr.Search("apple") {
		t.Error("expected apple found")
	}
	if !tr.Search("app") {
		t.Error("expected app found")
	}
	if tr.Search("ap") {
		t.Error("ap should not be found")
	}
}

func TestSearchEmpty(t *testing.T) {
	tr := trie.New()
	if tr.Search("anything") {
		t.Error("empty trie should not find anything")
	}
}

func TestDelete(t *testing.T) {
	tr := trie.New()
	tr.Insert("hello")
	tr.Insert("help")
	if !tr.Delete("hello") {
		t.Error("expected delete to return true")
	}
	if tr.Search("hello") {
		t.Error("hello should be deleted")
	}
	if !tr.Search("help") {
		t.Error("help should still exist")
	}
}

func TestDeleteMissing(t *testing.T) {
	tr := trie.New()
	if tr.Delete("missing") {
		t.Error("delete of missing word should return false")
	}
}

func TestStartsWith(t *testing.T) {
	tr := trie.New()
	tr.Insert("apple")
	tr.Insert("app")
	tr.Insert("application")
	tr.Insert("banana")
	result := tr.StartsWith("app")
	sort.Strings(result)
	expected := []string{"app", "apple", "application"}
	if len(result) != len(expected) {
		t.Fatalf("expected %v got %v", expected, result)
	}
	for i := range expected {
		if result[i] != expected[i] {
			t.Errorf("mismatch: %s != %s", result[i], expected[i])
		}
	}
}

func TestStartsWithNoMatch(t *testing.T) {
	tr := trie.New()
	tr.Insert("hello")
	if len(tr.StartsWith("xyz")) != 0 {
		t.Error("expected empty result for non-matching prefix")
	}
}
